"""Does the evening have less supply after a deep midday trough? Fitting period, hourly (notes 21.85)."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import market1 as M
SP = M.SP; P = np.load(f"{SP}/out/market1n_post.npz"); th = {k: float(np.median(P[k])) for k in M.PN}; R = pd.read_parquet(f"{SP}/out/market1n_rows.parquet"); kn = np.median(P["kn"], 0); NBC = [f"rl_{c}" for c in ("fr", "nl", "be", "at", "pl", "cz", "ch", "dk")]; R["nb"] = ((R[NBC].values - P["NMU"]) / P["NSD"]) @ kn; R["Dp"] = R.rl - R.other
wd = th["K_s"] * (R.p < -M.EPS) + 0.5 * th["K_s"] * (R.p.abs() <= M.EPS); R["u"] = R.Dp - (M.supply(th, R.p.values, R.L.values, R.co2.values) - wd) - R.nb; R["th"] = R.lig + R.coal + R.gasg; R["shT"] = R.d_l + R.d_c + R.d_g; R["r"] = R.p / R.L; DA = pd.read_parquet(f"{SP}/out/da_rows.parquet")[["disp_da", "np"]]; R = R.join(DA, how="left"); h = R.index.hour; R["day"] = R.index.normalize()
ev = R[(h >= 17) & (h <= 20)].groupby("day").agg(u_ev=("u", "mean"), D_ev=("Dp", "mean"), p_ev=("p", "mean"), r_ev=("r", "mean"), th_ev=("th", "mean"), shT_ev=("shT", "mean"), eX_ev=("eX", "mean"), eS_ev=("eS", "mean"), disp_ev=("disp_da", "mean"), X_ev=("X", "mean"), tr=("tr", "first"), n=("u", "size")); md = R[(h >= 10) & (h <= 15)].groupby("day").agg(D_md=("Dp", "min"), p_md=("p", "min"), u_md=("u", "mean"), th_md=("th", "mean"), r_md=("r", "mean")); ng = R[h < 6].groupby("day").agg(u_ng=("u", "mean"), D_ng=("Dp", "mean"), th_ng=("th", "mean"))
G = ev.join(md).join(ng).dropna(subset=["u_ev", "D_md", "u_ng"]); G = G[G.n == 4]; G["month"] = G.index.month; G["trough"] = G.D_ev - G.D_md
def ols(y, X, names):
    X = np.column_stack([X, np.ones(len(y))]); b = np.linalg.lstsq(X, y, rcond=None)[0]; r = y - X @ b; n, k = X.shape; cov = np.linalg.inv(X.T @ X) @ (X.T * r ** 2) @ X @ np.linalg.inv(X.T @ X) * n / (n - k); return "  ".join(f"{a} {c:+.3f} ±{s:.3f}" for a, c, s in zip(names, b, np.sqrt(np.diag(cov)))) + f" | R2 {1 - r.var() / y.var():.3f}"
for lab, S in (("fitting period, all days", G[G.tr]), ("fitting, April-September", G[G.tr & G.month.between(4, 9)]), ("fitting, October-March", G[G.tr & ~G.month.between(4, 9)]), ("after Dec 2025 (includes scored days; description only)", G[~G.tr])):
    print(lab, len(S), "days | evening shift mean", round(S.u_ev.mean(), 2), "sd", round(S.u_ev.std(), 2), "| midday trough depth (evening demand - midday minimum) mean", round(S.trough.mean(), 1), "sd", round(S.trough.std(), 1))
    print("   evening shift on evening demand:", ols(S.u_ev.values, S[["D_ev"]].values, ["D_ev"])); print("   + midday demand minimum:", ols(S.u_ev.values, S[["D_ev", "D_md"]].values, ["D_ev", "D_midday_min"])); print("   + night shift of the same day (known by the time of the evening, not at issue):", ols(S.u_ev.values, S[["D_ev", "D_md", "u_ng"]].values, ["D_ev", "D_midday_min", "u_night"])); print("   + midday shift instead:", ols(S.u_ev.values, S[["D_ev", "D_md", "u_md"]].values, ["D_ev", "D_midday_min", "u_midday"]))
    print("   evening thermal output on evening price/cost, evening demand, midday thermal output:", ols(S.th_ev.values, S[["r_ev", "D_ev", "th_md"]].values, ["r_ev", "D_ev", "thermal_midday"])); print("   evening thermal-vs-curve shock on midday demand minimum, evening demand:", ols(S.shT_ev.values, S[["D_ev", "D_md"]].values, ["D_ev", "D_midday_min"])); print("   evening import shock on the same:", ols(S.eX_ev.values, S[["D_ev", "D_md"]].values, ["D_ev", "D_midday_min"]))
S = G[G.tr & G.month.between(4, 9)]; q = S.trough.quantile([0.33, 0.67]).values; print("April-September, by depth of the midday trough (terciles): days, evening demand, evening price ct, evening shift, thermal evening, thermal midday, thermal shock evening, import shock evening"); 
for nm, m in (("shallow", S.trough <= q[0]), ("middle", (S.trough > q[0]) & (S.trough <= q[1])), ("deep", S.trough > q[1])): print(f"   {nm:8s} {int(m.sum()):4d}  D_ev {S.D_ev[m].mean():5.1f}  price {S.p_ev[m].mean() / 10:5.1f}  shift {S.u_ev[m].mean():+5.1f}  thermal ev {S.th_ev[m].mean():5.1f}  thermal midday {S.th_md[m].mean():5.1f}  thermal shock {S.shT_ev[m].mean():+5.2f}  import shock {S.eX_ev[m].mean():+5.2f}  midday min price {S.p_md[m].mean() / 10:5.1f}")
G.to_csv(f"{SP}/out/eve_days.csv")
